#!/usr/bin/env node

/**
 * Generate Placeholder Sound Files for HerdTracker
 *
 * This script creates silent MP3 placeholder files for the RFID scanner sound feedback.
 * These are temporary files to prevent app crashes until real sound files are added.
 *
 * Usage:
 *   node scripts/generate-placeholder-sounds.js
 *
 * OR on Unix/Mac:
 *   chmod +x scripts/generate-placeholder-sounds.js
 *   ./scripts/generate-placeholder-sounds.js
 */

const fs = require('fs');
const path = require('path');

// Base64-encoded silent MP3 (0.1 seconds, 44.1kHz, mono)
// This is a valid MP3 file with no audio data
const SILENT_MP3_BASE64 = '';

const soundFiles = [
  'beep_neutral.mp3',
  'beep_success.mp3',
  'beep_error.mp3'
];

const soundsDir = path.join(__dirname, '..', 'app', 'assets', 'sounds');

console.log('🔊 HerdTracker Sound Placeholder Generator');
console.log('==========================================\n');

// Ensure sounds directory exists
if (!fs.existsSync(soundsDir)) {
  console.log('📁 Creating sounds directory...');
  fs.mkdirSync(soundsDir, { recursive: true });
  console.log('✅ Directory created: app/assets/sounds/\n');
} else {
  console.log('✅ Sounds directory exists\n');
}

// Generate placeholder files
console.log('Generating placeholder sound files...\n');

let created = 0;
let skipped = 0;

soundFiles.forEach(filename => {
  const filePath = path.join(soundsDir, filename);

  if (fs.existsSync(filePath)) {
    console.log(`⏭️  ${filename} - Already exists (skipping)`);
    skipped++;
  } else {
    // Decode base64 and write to file
    const buffer = Buffer.from(SILENT_MP3_BASE64, 'base64');
    fs.writeFileSync(filePath, buffer);
    console.log(`✅ ${filename} - Created (${buffer.length} bytes)`);
    created++;
  }
});

console.log('\n==========================================');
console.log(`Summary: ${created} created, ${skipped} skipped`);

if (created > 0) {
  console.log('\n⚠️  IMPORTANT: These are SILENT placeholder files!');
  console.log('Replace them with real beep sounds for production.');
  console.log('See app/assets/sounds/README.md for instructions.\n');
} else {
  console.log('\n✨ All sound files already exist!\n');
}

console.log('Next steps:');
console.log('1. Run the app to test RFID scanner initialization');
console.log('2. Replace placeholder sounds with real audio files');
console.log('3. Test on physical Chafon C6 scanner device\n');
